// 데모 모드 버전
export const getItems = async () => {
  return [
    { itemNo: 1, itemName: "데모 상품 A" },
    { itemNo: 2, itemName: "데모 상품 B" },
    { itemNo: 3, itemName: "데모 상품 C" },
    { itemNo: 4, itemName: "데모 상품 D" },
  ];
};

export const getForecastSeries = async (itemNo, h = 12) => {
  return {
    itemNo,
    horizon: h,
    series: [
      { ym: "2025-01", qty: 120 },
      { ym: "2025-02", qty: 140 },
      { ym: "2025-03", qty: 160 },
    ],
  };
};
